// PI-201过高联锁保护脚本
// 触发条件：当PI-201压力值变化事件发生时执行

function on_event(event_data) {
    var pi201_value = read_tag("PI-201");
    var high_limit = 150.0;  // 高压阈值，请根据实际工艺调整

    if (pi201_value > high_limit) {
        log("WARNING: PI-201压力过高, 当前值=" + pi201_value + ", 阈值=" + high_limit);
        write_tag("valve1", true);  // 置位valve1，打开泄压阀
        log("ACTION: valve1已置位(ON)");
    }
}

