// 1号泵启停控制脚本
// 当操作员在HMI点击启动/停止按钮时触发

// 获取控制命令
var cmd = getTag("PUMP_01_CMD");

// 记录操作日志
if (cmd === 1) {
    log("操作员发出启动命令 - 1号泵");

    // 检查是否有故障
    var fault = getTag("PUMP_01_FAULT");
    if (fault === 1) {
        log("WARNING: 1号泵存在故障，无法启动");
        return;
    }

    // 模拟启动过程
    log("1号泵正在启动...");

} else {
    log("操作员发出停止命令 - 1号泵");
    log("1号泵正在停止...");
}

