// 1号泵运行参数监控脚本
// 每5秒执行一次，监控运行状态

var running = getTag("PUMP_01_RUN");
var flow = getTag("PUMP_01_FLOW");
var pressure = getTag("PUMP_01_PRESSURE");
var current = getTag("PUMP_01_CURRENT");

// 泵运行时检查参数是否正常
if (running === 1) {
    // 检查流量是否过低（可能是空转）
    if (flow < 5) {
        log("WARNING: 1号泵流量过低，可能存在空转风险");
    }

    // 检查电流是否过高
    if (current > 250) {
        log("WARNING: 1号泵电流过高 (" + current + "A)");
    }
}

